  offsetHeight,
  scrollHeight = 1000,
  scrollTop = 0,
}: CreateContainerArgs): HTMLElement => {
  const container = document.createElement('div');

  Object.defineProperties(container, {
    offsetHeight: {
      configurable: true,
      value: offsetHeight,
    },
    scrollHeight: {
      configurable: true,
      value: scrollHeight,
    },
    scrollTop: {
      configurable: true,
      value: scrollTop,
      writable: true,
    },
  });

  return container;
};

