        filter: { operator: 'equals', type: 'multiSelect', values: ['A'] },
      }),
    ).toEqual(['A']);
  });

  it('dispatches number filter', () => {
    expect(
      serializeFilter({
        filter: { operator: 'equals', type: 'number', value: 1 },
      }),
    ).toEqual(['eq', 1]);
  });

